/**
 * The project's shared framework Logger. Silent unless WP_DEBUG.
 *
 * @return \rtCamp\WPFramework\Utils\Logger Shared logger.
 */
public static function logger(): \rtCamp\WPFramework\Utils\Logger {
	static $instance = null;

	if ( null === $instance ) {
		$instance = new \rtCamp\WPFramework\Utils\Logger( '{{context_slug}}' );
	}

	return $instance;
}
